sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_lvClipBlack;
uniform float amzp_lvClipWhite;
uniform float amzp_lvMix;
uniform float amzp_lvMInBlack;
uniform float amzp_lvMInWhite;
uniform float amzp_lvMGamma;
uniform float amzp_lvMOutBlack;
uniform float amzp_lvMOutWhite;
uniform float amzp_lvRInBlack;
uniform float amzp_lvRInWhite;
uniform float amzp_lvRGamma;
uniform float amzp_lvROutBlack;
uniform float amzp_lvROutWhite;
uniform float amzp_lvGInBlack;
uniform float amzp_lvGInWhite;
uniform float amzp_lvGGamma;
uniform float amzp_lvGOutBlack;
uniform float amzp_lvGOutWhite;
uniform float amzp_lvBInBlack;
uniform float amzp_lvBInWhite;
uniform float amzp_lvBGamma;
uniform float amzp_lvBOutBlack;
uniform float amzp_lvBOutWhite;
uniform float amzp_lvAInBlack;
uniform float amzp_lvAInWhite;
uniform float amzp_lvAGamma;
uniform float amzp_lvAOutBlack;
uniform float amzp_lvAOutWhite;
    float lvl(float c, float ib, float iw, float g, float ob, float ow) {
        float t = (c * 255.0 - ib) / max(iw - ib, 0.0001);
        if ((amzp_lvClipBlack>0.5)) t = max(t, 0.0);
        if ((amzp_lvClipWhite>0.5)) t = min(t, 1.0);
        t = t >= 0.0 ? pow(t, 1.0 / max(g, 0.001)) : t;
        return (ob + t * (ow - ob)) / 255.0;
    }
    void amzRender() {
        float4 src = amzTexture(0, amzScreenNorm());
        float a = src.a;
        float3 c = a > 0.00001 ? src.rgb / a : float3(0.0);
        c.r = lvl(c.r, amzp_lvRInBlack, amzp_lvRInWhite, amzp_lvRGamma, amzp_lvROutBlack, amzp_lvROutWhite);
        c.g = lvl(c.g, amzp_lvGInBlack, amzp_lvGInWhite, amzp_lvGGamma, amzp_lvGOutBlack, amzp_lvGOutWhite);
        c.b = lvl(c.b, amzp_lvBInBlack, amzp_lvBInWhite, amzp_lvBGamma, amzp_lvBOutBlack, amzp_lvBOutWhite);
        c.r = lvl(c.r, amzp_lvMInBlack, amzp_lvMInWhite, amzp_lvMGamma, amzp_lvMOutBlack, amzp_lvMOutWhite);
        c.g = lvl(c.g, amzp_lvMInBlack, amzp_lvMInWhite, amzp_lvMGamma, amzp_lvMOutBlack, amzp_lvMOutWhite);
        c.b = lvl(c.b, amzp_lvMInBlack, amzp_lvMInWhite, amzp_lvMGamma, amzp_lvMOutBlack, amzp_lvMOutWhite);
        float na = clamp(lvl(a, amzp_lvAInBlack, amzp_lvAInWhite, amzp_lvAGamma, amzp_lvAOutBlack, amzp_lvAOutWhite), 0.0, 1.0);
        float4 outc = float4(clamp(c, 0.0, 1.0) * na, na);
        amzOutput = mix(src, outc, clamp(amzp_lvMix, 0.0, 1.0));
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
